fs = 1000; t = (0:999)'/fs;
x = sin(2*pi*100*t) + 0.5*sin(2*pi*200*t);
fprintf('total: %.4f\n', bandpower(x));
fprintf('50 to 150 Hz: %.4f\n', bandpower(x, fs, [50 150]));
fprintf('150 to 250 Hz: %.4f\n', bandpower(x, fs, [150 250]));

fprintf('rectangular: %.4f bins
', enbw(rectwin(64)));
fprintf('hamming:     %.4f bins
', enbw(hamming(64)));
fprintf('hamming at fs = 1000: %.4f Hz
', enbw(hamming(64), 1000));

fs = 1000; t = (0:255)'/fs;
y = exp(1i*2*pi*100*t) + (t > 0.128).*exp(1i*2*pi*300*t);
[bw, tm] = instbw(y, fs);
fprintf('%d estimates, first at %.3f s\n', numel(bw), tm(1));
disp(round(bw([1 5 10 15 20 25 29])'))

fs = 1000; t = (0:255)'/fs;
y = exp(1i*2*pi*(50*t + 50*t.^2));
[f, tm] = instfreq(y, fs);
fprintf('%d estimates\n', numel(f));
disp(round(f([1 10 20 29])'))
disp(round(tm([1 10 20 29])'*1000)/1000)

fs = 1000; t = (0:255)'/fs;
x = cos(2*pi*(50*t + 50*t.^2));
f = instfreq(x, fs, 'Method', 'hilbert');
disp(numel(f))
disp(round(f([20 100 200])'))

fs = 1000; t = (0:999)'/fs;
x = sin(2*pi*100*t) + 0.5*sin(2*pi*200*t);
[bw, flo, fhi, pw] = obw(x, fs);
fprintf('%.1f Hz wide, from %.1f to %.1f Hz\n', bw, flo, fhi);
fprintf('power inside: %.4f\n', pw);

fs = 1000; t = (0:999)'/fs;
x = sin(2*pi*100.5*t);
[bw, flo, fhi, pw] = powerbw(x, fs);
fprintf('%.2f Hz wide, from %.2f to %.2f Hz\n', bw, flo, fhi);
fprintf('power inside: %.4f\n', pw);

n = (0:1023)';
x = sin(2*pi*77.3*n/1000) + 0.1*sin(2*pi*2*77.3*n/1000+0.3) + 0.05*sin(2*pi*3*77.3*n/1000+1);
[r, spurpow, spurfreq] = sfdr(x, 1000);
fprintf('SFDR: %.2f dB\n', r);
fprintf('largest spur: %.2f dB at %.1f Hz\n', spurpow, spurfreq);

n = (0:1023)';
x = sin(2*pi*77.3*n/1000) + 0.1*sin(2*pi*2*77.3*n/1000+0.3) + 0.05*sin(2*pi*3*77.3*n/1000+1);
[r, np] = sinad(x, 1000);
fprintf('SINAD: %.2f dB\n', r);
fprintf('noise and distortion power: %.2f dB\n', np);

n = (0:2047)';
u = 0.01*(sin(2*pi*200*n/2000) + sin(2*pi*250*n/2000));
y = u + 100*u.^3;
[p, fp, ff, ip, if_] = toi(y, 2000);
fprintf('OIP3: %.2f dB\n', p);
disp(round(ff'))
disp(round(if_'))

x = [2 1 0.5 0.25];
[xh, nd] = cceps(x);
disp(nd)
disp(round(xh*1e4)/1e4)
disp(round(icceps(xh, nd)*1e4)/1e4)

fs = 1000; n = (0:255)';
x = sin(2*pi*100*n/fs);
a = exp(1i*2*pi*90/fs);
w = exp(-1i*2*pi*1/fs);
X = czt(x, 21, w, a);
[~, k] = max(abs(X));
fprintf('peak at %d Hz\n', 90 + k - 1);
fprintf('max |X| = %.2f\n', max(abs(X)));

x = [1 2 3 4];
disp(round(czt(x)*1e3)/1e3)
disp(round(fft(x)*1e3)/1e3)

x = [1 2 3 4];
c = dct(x);
disp(round(c*1e4)/1e4)
disp(round(idct(c)*1e4)/1e4)

x = [1; 2; 3; 4];
D = dftmtx(4);
disp(round(D*x*1e3)/1e3)
disp(round(fft(x)*1e3)/1e3)

x = [1 2 3 4];
y = fwht(x);
disp(y)
disp(ifwht(y))
disp(fwht(x, 4, 'hadamard'))

n = (0:63)';
x = cos(2*pi*8*n/64);
X = fft(x);
fprintf('%.4f\n', abs(goertzel(x, 9)));
fprintf('%.4f\n', abs(X(9)));
disp(round(abs(goertzel(x, [9 13]))*1e4)/1e4)

n = 0:7;
x = cos(2*pi*n/8);
z = hilbert(x);
disp(round(real(z)*1e3)/1e3)
disp(round(imag(z)*1e3)/1e3)
disp(round(abs(z)*1e3)/1e3)

x = [2 1 0.5 0.25];
[xh, nd] = cceps(x);
y = icceps(xh, nd);
disp(round(y*1e4)/1e4)

c = dct([1 2 3 4]);
c(3:4) = 0;
disp(round(idct(c)*1e3)/1e3)

x = [4 1 0 3 2 2 1 0];
y = fwht(x);
disp(y)
disp(ifwht(y))

x = [1 2 3 4 zeros(1, 60)];
[y, ym] = rceps(x);
disp(ym(1:5))
fprintf('%.3f\n', max(abs(abs(fft(ym)) - abs(fft(x)))))

a = [1 2 3];
b = [1 1];
disp(cconv(a, b, 3))
disp(cconv(a, b, 4))
disp(conv(a, b))

h = [1; 2; 3];
T = convmtx(h, 2);
disp(T)
disp((T*[1; 1])')
disp(conv(h', [1 1]))

x = (1:5)';
X = corrmtx(x, 2);
disp(size(X))
disp(round(X*1e3)/1e3)

a = [1 2; 3 4];
b = [1 1; 1 1];
disp(xcorr2(a, b))
disp(xcorr2(a))
